import pandas as pd
import numpy as np

train = pd.read_csv('train.csv')
test = pd.read_csv('test.csv')
feat_cols = [c for c in train.columns if c != 'target']

X_train = train[feat_cols].to_numpy(float)
y_train = train['target'].to_numpy(float)
X_test = test[feat_cols].to_numpy(float)
y_test = test['target'].to_numpy(float)

# Try: find 2-3 feature threshold combinations
# Use median-based thresholds
medians = np.median(X_train, axis=0)
X_tr_bin = (X_train > medians).astype(int)
X_te_bin = (X_test > medians).astype(int)

# For each pair of features and each direction (above/below median), count accuracy
from itertools import combinations
results = []
for i, j in combinations(range(50), 2):
    for di in [0, 1]:
        for dj in [0, 1]:
            mask = (X_tr_bin[:, i] == di) & (X_tr_bin[:, j] == dj)
            if mask.sum() >= 3:  # at least 3 samples
                purity = y_train[mask].mean()
                if purity == 1.0 or purity == 0.0:
                    # Perfectly pure rule
                    test_mask = (X_te_bin[:, i] == di) & (X_te_bin[:, j] == dj)
                    if test_mask.any():
                        rule_pred = 1 if purity == 1.0 else 0
                        results.append((i, j, di, dj, rule_pred, mask.sum(), test_mask.sum()))

if results:
