                        results.append((i, j, k, di, dj, dk, rule_pred, mask.sum(), test_mask.sum()))

if len(results) > 0:
    results.sort(key=lambda x: -x[8])
    print(f'Total matching rules: {len(results)}')
    for r in results[:5]:
        if len(r) == 7:
            print(f'  2-feat: {feat_cols[r[0]]} {r[2]} AND {feat_cols[r[1]]} {r[3]} => {r[4]} ({r[5]} train, {r[6]} test)')
